uint32_t g_routingOverheadCount = 0;

// Vehicles already wired up by the random-requesters block, so the
// hazard-broadcast block can avoid double-booking the same vehicle
// with a second, conflicting Consumer app setup.
std::set<uint32_t> g_randomRequesterVehicles;

