// ---- Live SUMO co-simulation bridge globals (Phase 2) ----------------
class SumoBridgeClient;
SumoBridgeClient* g_bridgeClientPtr = nullptr;
std::map<std::string, uint32_t>* g_sumoIdToNodeIndexPtr = nullptr;
std::map<uint32_t, std::string>* g_nodeIndexToSumoIdPtr = nullptr;

void
PrintScheduledMessage(std::string msg)
{
  std::cout << msg << std::endl;
}

void
SwitchRouteByDevice(Ptr<Node> node, std::string prefix,
                     Ptr<NetDevice> deadDevice, Ptr<NetDevice> newDevice, std::string label)
{
  Ptr<ndn::L3Protocol> l3 = node->GetObject<ndn::L3Protocol>();
  shared_ptr<ndn::Face> deadFace = l3->getFaceByNetDevice(deadDevice);
  shared_ptr<ndn::Face> newFace = l3->getFaceByNetDevice(newDevice);
  if (deadFace != nullptr) { ndn::FibHelper::RemoveRoute(node, prefix, deadFace); g_routingOverheadCount++; }
  if (newFace != nullptr) { ndn::FibHelper::AddRoute(node, prefix, newFace, 0); g_routingOverheadCount++; }
  std::cout << "  [" << label << "] Node" << node->GetId() << " switched its route for " << prefix << std::endl;
}

// Outage bookkeeping per (originRsuId, destRsuId): while now < value, a VCF
// mule or range-boost is already handling that pair, so retries must not
// start another handoff.
std::map<std::pair<std::string, std::string>, double> g_vcfBusyUntil;
// Directed RSU pairs whose PRIMARY backbone link is currently failed.
std::set<std::pair<std::string, std::string>> g_pairDown;
// Vehicles busy with their own requests, and each broken-down vehicle's breakdown time:
// neither may serve as a VCF ferry or a last-mile carry relay.
std::set<uint32_t> g_requesterVehicles;
std::map<uint32_t, double> g_brokenAt;
// Baseline switches (both on by default): --vcf=false turns off the data ferries,
// --rangeBoost=false turns off the range-boost fallback.
bool g_vcfEnabled = true;
bool g_rangeBoostEnabled = true;

// Replace EVERY next hop of `prefix` on `node` with one route via `viaDevice`.
// Adding a hop without removing earlier ones (e.g. a previous mule) leaves
// stale equal-cost routes that the forwarder may keep using.
void
SetSoleRoute(Ptr<Node> node, std::string prefix, Ptr<NetDevice> viaDevice, std::string label)
{
  Ptr<ndn::L3Protocol> l3 = node->GetObject<ndn::L3Protocol>();
  shared_ptr<ndn::Face> newFace = l3->getFaceByNetDevice(viaDevice);
  const nfd::fib::Entry* entry = l3->getForwarder()->getFib().findExactMatch(ndn::Name(prefix));
  if (entry != nullptr) {
    std::vector<shared_ptr<ndn::Face>> old;
    for (const auto& nh : entry->getNextHops()) {
      if (newFace == nullptr || nh.getFace().getId() != newFace->getId())
        old.push_back(nh.getFace().shared_from_this());
    }
    for (auto& f : old) { ndn::FibHelper::RemoveRoute(node, prefix, f); g_routingOverheadCount++; }
  }
  if (newFace != nullptr) { ndn::FibHelper::AddRoute(node, prefix, newFace, 0); g_routingOverheadCount++; }
  std::cout << "  [" << label << "] Node" << node->GetId() << " now routes " << prefix
            << " via a single next hop at t=" << Simulator::Now().GetSeconds() << "s" << std::endl;
}

// Like SetSoleRoute, but adds the new next hop BEFORE removing the old ones, so the
// FIB entry is never empty (an empty entry lets NFD erase the name-tree node while
// PIT entries still refer to it -> Pit::erase assertion under many simultaneous changes).
void
SwapRoute(Ptr<Node> node, std::string prefix, Ptr<NetDevice> viaDevice, std::string label)
{
  Ptr<ndn::L3Protocol> l3 = node->GetObject<ndn::L3Protocol>();
  shared_ptr<ndn::Face> newFace = l3->getFaceByNetDevice(viaDevice);
  if (newFace == nullptr) return;
  std::vector<shared_ptr<ndn::Face>> old;
  const nfd::fib::Entry* entry = l3->getForwarder()->getFib().findExactMatch(ndn::Name(prefix));
  if (entry != nullptr)
    for (const auto& nh : entry->getNextHops())
      if (nh.getFace().getId() != newFace->getId()) old.push_back(nh.getFace().shared_from_this());
  ndn::FibHelper::AddRoute(node, prefix, newFace, 0); g_routingOverheadCount++;
  for (auto& f : old) { ndn::FibHelper::RemoveRoute(node, prefix, f); g_routingOverheadCount++; }
  std::cout << "  [" << label << "] Node" << node->GetId() << " now routes " << prefix
            << " via a single next hop at t=" << Simulator::Now().GetSeconds() << "s" << std::endl;
}

void
RemoveRouteVia(Ptr<Node> node, std::string prefix, Ptr<NetDevice> viaDevice)
{
  Ptr<ndn::L3Protocol> l3 = node->GetObject<ndn::L3Protocol>();
  shared_ptr<ndn::Face> f = l3->getFaceByNetDevice(viaDevice);
  if (f != nullptr) { ndn::FibHelper::RemoveRoute(node, prefix, f); g_routingOverheadCount++; }
}

void
MarkPairDown(uint32_t i, uint32_t j, bool down)
{
  std::string a = "rsu" + std::to_string(i), b = "rsu" + std::to_string(j);
  if (down) { g_pairDown.insert({a, b}); g_pairDown.insert({b, a}); }
  else      { g_pairDown.erase({a, b});  g_pairDown.erase({b, a}); }
}

// Ferry delivery: only if the pair is STILL failed (a ferry dispatched just
// before recovery must not overwrite the restored primary route).
void
FerryDeliver(Ptr<Node> origin, std::string prefix, Ptr<NetDevice> viaDevice,
             std::string originId, std::string destId)
{
  if (!g_pairDown.count({originId, destId})) {
    std::cout << "  [FERRY-DELIVERY-SKIPPED] " << originId << "->" << destId
              << " already recovered at t=" << Simulator::Now().GetSeconds() << "s" << std::endl;
    return;
  }
  SetSoleRoute(origin, prefix, viaDevice, "FERRY-DELIVERY");
}

void
AddRelayRoute(Ptr<Node> node, std::string prefix, Ptr<NetDevice> viaDevice, std::string label)
{
  Ptr<ndn::L3Protocol> l3 = node->GetObject<ndn::L3Protocol>();
  shared_ptr<ndn::Face> face = l3->getFaceByNetDevice(viaDevice);
  if (face != nullptr) {
    ndn::FibHelper::AddRoute(node, prefix, face, 0);
    g_routingOverheadCount++;
    std::cout << "  [" << label << "] Node" << node->GetId() << " can now relay " << prefix << std::endl;

  }
}

// ---- Live SUMO co-simulation bridge (Phase 2) -------------------------
// Speaks the tiny newline-delimited text protocol implemented by
// sumo_bridge_server.py: STEP returns every currently-active SUMO
// vehicle's live position/speed/lane; BREAKDOWN <sumoId> issues a real,
// live SUMO stop (setSpeed(0)) so trailing traffic genuinely reacts --
// confirmed via realistic deceleration + lane-change avoidance in
// standalone bridge testing before this integration. Entirely optional:
// only used when --liveCoSim=true is passed; the default path still
// reads the offline Ns2Mobility trace exactly as before.
extern NodeContainer* g_vehicleNodesPtr;  // defined later in this file; forward-declared here so the bridge code (inserted earlier) can see it
class SumoBridgeClient {
public:
  struct VehState {
    double x, y, angle, speed;
    std::string lane;
  };

  bool
  Connect(const std::string& host, uint16_t port)
  {
    m_sock = socket(AF_INET, SOCK_STREAM, 0);
    if (m_sock < 0) {
      std::cerr << "[BRIDGE-CLIENT] socket() failed" << std::endl;
      return false;
    }
    sockaddr_in addr;
    std::memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(port);
    if (inet_pton(AF_INET, host.c_str(), &addr.sin_addr) <= 0) {
      std::cerr << "[BRIDGE-CLIENT] invalid host: " << host << std::endl;
      return false;
    }
    if (connect(m_sock, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0) {
      std::cerr << "[BRIDGE-CLIENT] connect() to " << host << ":" << port << " failed" << std::endl;
      return false;
    }
    m_connected = true;
    std::cout << "[BRIDGE-CLIENT] Connected to bridge at " << host << ":" << port << std::endl;
    return true;
  }

  // Sends one command line, reads the reply up to its terminating blank
  // line, and returns every non-empty reply line. Fully synchronous --
  // one command in flight at a time, matching sumo_bridge_server.py.
  std::vector<std::string>
  SendCommand(const std::string& cmd)
  {
    std::vector<std::string> lines;
    if (!m_connected) return lines;
    std::string toSend = cmd + "\n";
    if (send(m_sock, toSend.c_str(), toSend.size(), 0) < 0) {
      std::cerr << "[BRIDGE-CLIENT] send() failed" << std::endl;
      m_connected = false;
      return lines;
    }

    std::string buffer;
    char chunk[4096];
    while (true) {
      auto pos = buffer.find("\n\n");
      if (pos != std::string::npos) {
        std::string complete = buffer.substr(0, pos);
        std::stringstream ss(complete);
        std::string line;
        while (std::getline(ss, line)) {
          if (!line.empty()) lines.push_back(line);
        }
        return lines;
      }
      ssize_t n = recv(m_sock, chunk, sizeof(chunk), 0);
      if (n <= 0) {
        std::cerr << "[BRIDGE-CLIENT] recv() failed or connection closed" << std::endl;
        m_connected = false;
        return lines;
      }
      buffer.append(chunk, static_cast<size_t>(n));
    }
  }

  std::map<std::string, VehState>
  Step()
  {
    std::map<std::string, VehState> out;
    auto lines = SendCommand("STEP");
    for (auto& line : lines) {
      if (line.rfind("VEH ", 0) != 0) continue;
      std::stringstream ss(line);
      std::string tag, id, lane;
      double x, y, angle, speed;
      ss >> tag >> id >> x >> y >> angle >> speed >> lane;
      out[id] = VehState{x, y, angle, speed, lane};
    }
    return out;
  }

  // Warned vehicle reacts in SUMO (lane change if needed + slow down).
  std::string
  HazardAction(const std::string& sumoId, const std::string& hazardSumoId)
  {
    auto lines = SendCommand("ACTION " + sumoId + " " + hazardSumoId);
    if (lines.empty()) return "no action (no bridge reply)";
    const std::string ok = "OK ACTION ";
    if (lines[0].rfind(ok, 0) == 0) return lines[0].substr(ok.size());
    return "no action (" + lines[0] + ")";
  }

  bool
  Breakdown(const std::string& sumoId)
  {
    auto lines = SendCommand("BREAKDOWN " + sumoId);
    for (auto& line : lines) {
      if (line.rfind("OK BREAKDOWN", 0) == 0) return true;
    }
    return false;
  }

  bool
  SendEvent(double x, double y, const std::string& text)
  {
    auto lines = SendCommand("EVENT " + std::to_string(x) + " " + std::to_string(y) + " " + text);
    for (auto& line : lines) {
      if (line.rfind("OK EVENT", 0) == 0) return true;
    }
    return false;
  }

private:
  int m_sock = -1;
  bool m_connected = false;
};

struct NodeMapEntry {
  std::string sumoId;
  uint32_t nodeIndex;
};

std::vector<NodeMapEntry>
LoadNodeMap(const std::string& filename)
{
  std::vector<NodeMapEntry> list;
  std::ifstream file(filename);
  if (!file.is_open()) {
    std::cerr << "[ERROR] Could not open node map file: " << filename << std::endl;
    return list;
  }
  std::string line;
  std::getline(file, line);  // header: sumo_vehicle_id,ns3_node_index
  while (std::getline(file, line)) {
    std::stringstream ss(line);
    std::string field;
    NodeMapEntry e;
    std::getline(ss, field, ','); e.sumoId = field;
    std::getline(ss, field, ','); e.nodeIndex = static_cast<uint32_t>(std::stoul(field));
    list.push_back(e);
  }
  return list;
}

void
BridgeStepAndReschedule(double stepInterval, double simDuration)
{
  if (g_bridgeClientPtr == nullptr || g_sumoIdToNodeIndexPtr == nullptr || g_vehicleNodesPtr == nullptr) {
    return;
  }
  auto states = g_bridgeClientPtr->Step();
  uint32_t updated = 0, unknown = 0;
  for (auto& kv : states) {
    auto it = g_sumoIdToNodeIndexPtr->find(kv.first);
    if (it == g_sumoIdToNodeIndexPtr->end()) {
      unknown++;
      continue;
    }
    Ptr<Node> node = g_vehicleNodesPtr->Get(it->second);
    Ptr<ConstantVelocityMobilityModel> mob = node->GetObject<ConstantVelocityMobilityModel>();
    if (mob == nullptr) { continue; }
    mob->SetPosition(Vector(kv.second.x, kv.second.y, 0.0));
    // SUMO angle: 0deg = North, clockwise. Convert speed+angle into an
    // (x,y) velocity vector so VCF-SELECT's GetVelocity()-based
    // speed/heading scoring sees real motion, matching the offline
    // Ns2MobilityHelper trace's behavior.
    double angleRad = kv.second.angle * M_PI / 180.0;
    double vx = kv.second.speed * std::sin(angleRad);
    double vy = kv.second.speed * std::cos(angleRad);
    mob->SetVelocity(Vector(vx, vy, 0.0));
    updated++;
  }
  if (unknown > 0) {
    std::cout << "[BRIDGE-STEP] t=" << Simulator::Now().GetSeconds()
              << "s updated=" << updated << " unknownSumoIds=" << unknown << std::endl;
  }

  if (Simulator::Now().GetSeconds() + stepInterval <= simDuration) {
    Simulator::Schedule(Seconds(stepInterval), &BridgeStepAndReschedule, stepInterval, simDuration);
  }
}

void
DashboardEvent(Ptr<Node> anchorNode, const std::string& text)
{
  static const char* kHidden[] = {"FERRY:", "VCF:", "RELAY:", "RANGE-BOOST:",
                                  "LAST-MILE-FAILED:", "HAZARD-WARN:"};
  for (const char* h : kHidden) if (text.rfind(h, 0) == 0) return;
  if (g_bridgeClientPtr == nullptr) {
    return;
  }
  double x = 0.0, y = 0.0;
  if (anchorNode != nullptr) {
    Ptr<MobilityModel> mob = anchorNode->GetObject<MobilityModel>();
    if (mob != nullptr) {
      Vector pos = mob->GetPosition();
      x = pos.x;
      y = pos.y;
    }
  }
  g_bridgeClientPtr->SendEvent(x, y, text);
}

// ---- RSU list and failure schedule loading ---------------------------

struct RsuListEntry {
  std::string id;
  double x, y;
};

std::vector<RsuListEntry>
LoadRsuList(const std::string& filename)
{
  std::vector<RsuListEntry> list;
  std::ifstream file(filename);
  if (!file.is_open()) {
    std::cerr << "[ERROR] Could not open RSU list file: " << filename << std::endl;
    return list;
  }
  std::string line;
  std::getline(file, line);  // header: rsu_id,x,y
  while (std::getline(file, line)) {
    std::stringstream ss(line);
    std::string field;
    RsuListEntry e;
    std::getline(ss, field, ','); e.id = field;
    std::getline(ss, field, ','); e.x = std::stod(field);
    std::getline(ss, field, ','); e.y = std::stod(field);
    list.push_back(e);
  }
  return list;
}

struct FailureEntry {
  std::string rsuId;
  double failStart, failEnd;
};

std::vector<FailureEntry>
LoadFailureSchedule(const std::string& filename)
{
  std::vector<FailureEntry> schedule;
  std::ifstream file(filename);
  if (!file.is_open()) {
    std::cerr << "[ERROR] Could not open failure schedule file: " << filename << std::endl;
    return schedule;
  }
  std::string line;
  std::getline(file, line);  // header: rsu_id,fail_start,fail_end
  while (std::getline(file, line)) {
    std::stringstream ss(line);
    std::string field;
    FailureEntry e;
    std::getline(ss, field, ','); e.rsuId = field;
    std::getline(ss, field, ','); e.failStart = std::stod(field);
    std::getline(ss, field, ','); e.failEnd = std::stod(field);
    schedule.push_back(e);
  }
  return schedule;
}

